const schema = {
  type: "object",
  required: ["from", "to", "amountKobo"],
  additionalProperties: false,
  properties: {
    from: { type: "integer" },
    to: { type: "integer" },
    amountKobo: { type: "integer", minimum: 1 },
  },
};

const CHECK = {
  object: (v) => typeof v === "object" && v !== null && !Array.isArray(v),
  string: (v) => typeof v === "string",
  integer: (v) => Number.isInteger(v),
};

function validate(schema, value, path = "$") {
  if (schema.type && !CHECK[schema.type](value)) return [`${path}: expected ${schema.type}`];
  const errors = [];
  if (schema.minimum !== undefined && value < schema.minimum) errors.push(`${path}: must be at least ${schema.minimum}`);
  if (schema.type === "object") {
    for (const name of schema.required ?? []) if (!(name in value)) errors.push(`${path}.${name}: is required`);
    for (const [name, child] of Object.entries(value)) {
      if (schema.properties?.[name]) errors.push(...validate(schema.properties[name], child, `${path}.${name}`));
      else if (schema.additionalProperties === false) errors.push(`${path}.${name}: is not allowed`);
    }
  }
  return errors;
}

console.log(validate(schema, { from: 1, to: 2, amountKobo: 1000000 }));
console.log(validate(schema, { from: 1, amountKobo: "5", x: true }));
console.log(validate(schema, { from: 1, to: 2, amountKobo: 0 }));
console.log(validate(schema, [1, 2]));

