const contract = {
  responses: {
    201: { fields: { id: "string", amountKobo: "integer" } },
    422: { fields: { title: "string", status: "integer" } },
  },
};

const is = { integer: Number.isInteger, string: (v) => typeof v === "string" };

function checkResponse(contract, status, body) {
  const schema = contract.responses[status];
  if (!schema) return `FAIL undocumented status ${status}`;
  const bad = Object.entries(schema.fields).filter(([field, type]) => !is[type](body[field])).map(([field]) => field);
  return bad.length ? `FAIL ${bad.join(", ")}` : "PASS";
}

console.log(checkResponse(contract, 201, { id: "41", amountKobo: 1000000 }));
console.log(checkResponse(contract, 201, { id: 41, amountKobo: "1000000" }));
console.log(checkResponse(contract, 422, { title: "Insufficient funds", status: 422 }));
console.log(checkResponse(contract, 500, { error: "oops" }));

