const before = {
  required: ["from", "to"],
  properties: { from: {}, to: {}, currency: { enum: ["NGN", "USD"] }, note: {} },
};
const after = {
  required: ["from", "to", "note", "channel"],
  properties: { from: {}, to: {}, currency: { enum: ["NGN"] }, note: {}, channel: {} },
};

function requestBreaks(before, after) {
  const problems = [];
  for (const name of after.required) {
    if (!before.required.includes(name)) problems.push(`${name} became required`);
  }
  for (const [name, old] of Object.entries(before.properties)) {
    const removed = (old.enum ?? []).filter((v) => !(after.properties[name]?.enum ?? old.enum).includes(v));
    if (removed.length) problems.push(`${name}: values ${removed} no longer accepted`);
  }
  return problems;
}

console.log(requestBreaks(before, after));

