const rows = [
  { id: 41, amount_kobo: 1000000, created_at: new Date(Date.UTC(2026, 8, 24, 10)) },
  { id: "42", amount_kobo: "250000", created_at: new Date(Date.UTC(2026, 8, 24, 11)) },
  { id: 43, amount_kobo: "12.50", created_at: new Date(Date.UTC(2026, 8, 24, 12)) },
];

function toTransfer(row) {
  const raw = row.amount_kobo;
  const amount = typeof raw === "string" && /^\d+$/.test(raw) ? Number(raw) : raw;
  if (!Number.isSafeInteger(amount)) throw new Error(`amount_kobo is not a whole number of kobo: ${raw}`);
  return { id: String(row.id), amountKobo: amount, createdAt: row.created_at.toISOString() };
}

for (const row of rows) {
  try {
    console.log(JSON.stringify(toTransfer(row)));
  } catch (error) {
    console.log(error.message);
  }
}

