let nextId = 1;
function publish(type, version, data) {
  if (!Number.isInteger(data.amountKobo) || data.amountKobo <= 0) throw new Error("invalid event: amountKobo");
  return { id: `evt-${nextId++}`, type, version, data };
}

const processed = new Set();
function handle(event) {
  if (processed.has(event.id)) return console.log(`${event.id}: duplicate, skipped`);
  processed.add(event.id);
  console.log(`${event.id}: SMS for ₦${event.data.amountKobo / 100}`);
}

const first = publish("transfer.completed", 2, { transferId: "41", amountKobo: 1000000 });
handle(first);
handle(first);
